<script setup lang="ts">
import { onMounted, onUnmounted, ref } from "vue";
import H5Header from "../components/H5Header.vue";
import BottomNav from "../components/BottomNav.vue";
import { clearLocalLibrary, favoriteItems, historyItems, listenHistoryItems } from "../library";
import { residentLogout, residentMe, type ResidentProfile } from "../api";
import { UserRound, Heart, Clock3, Headphones, Bell, Settings, SlidersHorizontal, Info, CircleHelp, ShieldCheck, ChevronRight, Trash2, LogOut, BadgeCheck } from "lucide-vue-next";
const favoriteCount = ref(0); const historyCount = ref(0); const listenCount = ref(0);
const profile = ref<ResidentProfile|null>(null);
function loadLibrary(){ favoriteCount.value=favoriteItems().length; historyCount.value=historyItems().length; listenCount.value=listenHistoryItems().length; }
function clear(){ if(window.confirm("确认清除本机收藏、浏览和收听历史吗？阅读设置将保留。")){ clearLocalLibrary(); loadLibrary(); } }
async function restoreProfile(){ if(!localStorage.getItem("jianda_resident_token")) return; try{ profile.value=await residentMe(); }catch{ localStorage.removeItem("jianda_resident_token"); localStorage.removeItem("jianda_resident_profile"); } }
async function logout(){ await residentLogout(); profile.value=null; }
onMounted(()=>{loadLibrary();restoreProfile();window.addEventListener("jianda-library-change",loadLibrary)}); onUnmounted(()=>window.removeEventListener("jianda-library-change",loadLibrary));
const links = [
  ["/membership", BadgeCheck, "简达安心会员", "增值权益，核心公共服务永久免费", "开通", () => ""], ["/reminders", Bell, "我的提醒", "报名截止、活动与办理时间", "查看", () => ""], ["/favorites", Heart, "我的收藏", "仍在公开的资讯与办事", "查看", () => `${favoriteCount.value} 条`],
  ["/history", Clock3, "历史浏览", "最近打开过的内容", "查看", () => `${historyCount.value} 条`], ["/listen?tab=recent", Headphones, "最近收听", "继续播放在本机听过的内容", "查看", () => `${listenCount.value} 条`],
  ["/neighborhood", UserRound, "我的帖子与评论", "参与当前地区邻里互动", "查看", () => ""], ["/settings", Settings, "阅读与语音设置", "字号、对比度和朗读速度", "设置", () => ""],
  ["/service-orders", Info, "我的订单", "已预约合作服务与订单状态", "查看", () => ""],
] as const;
</script>
<template><div class="h5-page profile-page-new"><H5Header/><main class="h5-main profile-page">
  <RouterLink to="/membership" class="member-banner"><span class="member-badge"><BadgeCheck/></span><div><b>简达安心会员</b><small>优先客服、深度办事指南、专属提醒；核心服务永久免费</small></div><ChevronRight/></RouterLink>
  <section v-if="profile" class="profile-hero"><div class="profile-avatar"><UserRound/></div><div class="profile-info"><h1>{{ profile.nickname }}</h1><p>{{ profile.district }} · {{ profile.streetOrTown }}<em v-if="profile.demo">DEMO</em></p><small>登录账号：{{ profile.username || profile.regionCode }}</small></div><button class="logout-btn" @click="logout"><LogOut/><span>退出</span></button></section>
  <section v-else class="profile-hero profile-hero--guest"><div class="profile-avatar"><UserRound/></div><div class="profile-info"><h1>游客浏览</h1><p>资讯、办事和本机收藏无需登录</p><small>居民账号用于邻里互动、预约合作服务</small></div><nav class="profile-entry"><RouterLink to="/resident/login">登录</RouterLink><RouterLink to="/resident/register">注册</RouterLink></nav></section>
  <section class="profile-stats"><div><b>{{ favoriteCount }}</b><small>收藏</small></div><div><b>{{ historyCount }}</b><small>浏览</small></div><div><b>{{ listenCount }}</b><small>收听</small></div><div><b>{{ profile ? 3 : 0 }}</b><small>提醒</small></div></section>
  <section class="profile-links"><RouterLink v-for="link in links" :key="link[2]" :to="link[0]"><span class="li-icon"><component :is="link[1]"/></span><span class="li-main"><b>{{ link[2] }}</b><small>{{ link[3] }}</small></span><span class="li-trail"><em v-if="link[5]()">{{ link[5]() }}</em><u>{{ link[4] }}</u><ChevronRight/></span></RouterLink></section>
  <section class="profile-foot"><div><CircleHelp/><span><b>帮助与反馈</b></span></div><div><ShieldCheck/><span><b>隐私说明</b></span></div><div><Info/><span><b>关于简达 v9.9.4</b></span></div></section>
  <button class="clear-local" type="button" @click="clear"><Trash2/>清除本机收藏和历史</button>
</main><BottomNav/><style scoped>
