.profile-page-new .clear-local{width:100%;min-height:52px;display:flex;align-items:center;justify-content:center;gap:7px;background:#fff;border:1px solid #E7ECE9;border-radius:12px;color:#B84A42;font-weight:700;margin:10px 0 18px;font-size:14px}.clear-local svg{width:18px}
@media(max-width:768px){.profile-page-new{padding-inline:16px}.member-banner{margin:0 0 14px;padding:18px}.profile-page-new .profile-hero{border-radius:0;margin-inline:-16px;border-left:0;border-right:0}.profile-page-new .profile-stats{padding:14px}.profile-stats b{font-size:19px}.profile-links a{padding:16px}.profile-page-new .profile-foot{grid-template-columns:1fr;gap:8px}}
